     * <p>Defaults to the build.compiler property but can be overridden
     * via the compiler attribute.</p>
     *
     * <p>This method does not take the fork attribute into
     * account.</p>
     *
     * @see #getCompiler
     * @return the compiler.
     *
     * @since Ant 1.5
     */
    public String getCompilerVersion() {
        facade.setMagicValue(getProject().getProperty("build.compiler"));
        return facade.getImplementation();
    }

    /**
     * Check that all required attributes have been set and nothing
     * silly has been entered.
     *
     * @since Ant 1.5
     * @exception BuildException if an error occurs
     */
    protected void checkParameters() throws BuildException {
        if (src == null) {
            throw new BuildException("srcdir attribute must be set!",
                                     getLocation());
        }
        if (src.size() == 0) {
            throw new BuildException("srcdir attribute must be set!",
                                     getLocation());
        }

        if (destDir != null && !destDir.isDirectory()) {
            throw new BuildException("destination directory \""
                                     + destDir
                                     + "\" does not exist "
                                     + "or is not a directory", getLocation());
        }
        if (includeAntRuntime == null && getProject().getProperty("build.sysclasspath") == null) {
            log(getLocation() + "warning: 'includeantruntime' was not set, " +
                    "defaulting to build.sysclasspath=last; set to false for repeatable builds",
                    Project.MSG_WARN);
        }
    }

    /**
     * Perform the compilation.
     *
     * @since Ant 1.5
     */
    protected void compile() {
        if (compileList.length == 0) {
            return;
        }

        logCompileStart();
        if (listFiles) {
            logFileList();
        }

        CompilerAdapter adapter = getAdapter();
        adapter.setJavac(this);

        boolean success = adapter.execute();
        if (success) {
            handleSuccess();
        } else {
            handleFailure();
        }
    }

    /**
     * Logs the initial compile message.
     */
    private void logCompileStart() {
        log("Compiling " + compileList.length + " source file"
            + (compileList.length == 1 ? "" : "s")
            + (destDir != null ? " to " + destDir : ""));
    }

    /**
     * Logs each source file when listFiles is enabled.
     */
    private void logFileList() {
        for (int i = 0; i < compileList.length; i++) {
            String filename = compileList[i].getAbsolutePath();
            log(filename);
        }
    }

    /**
     * Retrieves the compiler adapter for the current compiler.
     *
     * @return the configured CompilerAdapter
     */
    private CompilerAdapter getAdapter() {
        String compilerImpl = getCompiler();
        return nestedAdapter != null ? nestedAdapter :
            CompilerAdapterFactory.getCompiler(compilerImpl, this,
                                               createCompilerClasspath());
    }

    /**
     * Handles the successful compilation path.
     */
    private void handleSuccess() {
        if (createMissingPackageInfoClass) {
            try {
                File srcRoot = getProject().resolveFile(src.list()[0]);
                File destRoot = destDir != null ? destDir : srcRoot;
                generateMissingPackageInfoClasses(destRoot);
            } catch (IOException x) {
                throw new BuildException(x, getLocation());
            }
        }
    }

    /**
     * Handles the compilation failure path.
     */
    private void handleFailure() {
        taskSuccess = false;
        if (errorProperty != null) {
            getProject().setNewProperty(errorProperty, "true");
        }
        if (failOnError) {
            throw new BuildException(FAIL_MSG, getLocation());
        } else {
            log(FAIL_MSG, Project.MSG_ERR);
        }
    }

