    /**
     * Is the compiler implementation a jdk compiler
     *
     * @param compilerImpl the name of the compiler implementation
     * @return true if compilerImpl is "modern", "classic",
     * "javac1.1", "javac1.2", "javac1.3", "javac1.4", "javac1.5" or
     * "javac1.6".
     */
    protected boolean isJdkCompiler(String compilerImpl) {
        return MODERN.equals(compilerImpl)
            || CLASSIC.equals(compilerImpl)
            || JAVAC18.equals(compilerImpl)
            || JAVAC17.equals(compilerImpl)
            || JAVAC16.equals(compilerImpl)
            || JAVAC15.equals(compilerImpl)
            || JAVAC14.equals(compilerImpl)
            || JAVAC13.equals(compilerImpl)
            || JAVAC12.equals(compilerImpl)
            || JAVAC11.equals(compilerImpl);
    }

    /**
     * @return the executable name of the java compiler
     */
    protected String getSystemJavac() {
        return JavaEnvUtils.getJdkExecutable("javac");
    }

    /**
     * Choose the implementation for this particular task.
     * @param compiler the name of the compiler
     * @since Ant 1.5
     */
    public void setCompiler(String compiler) {
        facade.setImplementation(compiler);
    }

    /**
     * The implementation for this particular task.
     *
     * <p>Defaults to the build.compiler property but can be overridden
     * via the compiler and fork attributes.</p>
     *
     * <p>If fork has been set to true, the result will be extJavac
     * and not classic or java1.2 - no matter what the compiler
     * attribute looks like.</p>
     *
     * @see #getCompilerVersion
     * @return the compiler.
     * @since Ant 1.5
     */
    public String getCompiler() {
        String compilerImpl = getCompilerVersion();
        if (fork) {
            if (isJdkCompiler(compilerImpl)) {
                compilerImpl = EXTJAVAC;
            } else {
                log("Since compiler setting isn't classic or modern, "
                    + "ignoring fork setting.", Project.MSG_WARN);
            }
        }
        return compilerImpl;
    }

    /**
     * The implementation for this particular task.
     *
     * <p>Defaults to the build.compiler property but can be overridden
     * via the compiler attribute.</p>
     *
     * <p>This method does not take the fork attribute into
     * account.</p>
     *
     * @see #getCompiler
     * @return the compiler.
     *
     * @since Ant 1.5
     */
    public String getCompilerVersion() {
        facade.setMagicValue(getProject().getProperty("build.compiler"));
        return facade.getImplementation();
    }

    /**
     * Check that all required attributes have been set and nothing
     * silly has been entered.
     *
     * @since Ant 1.5
     * @exception BuildException if an error occurs
     */
    protected void checkParameters() throws BuildException {
        if (src == null) {
            throw new BuildException("srcdir attribute must be set!",
                                     getLocation());
        }
        if (src.size() == 0) {
            throw new BuildException("srcdir attribute must be set!",
                                     getLocation());
        }

        if (destDir != null && !destDir.isDirectory()) {
            throw new BuildException("destination directory \""
                                     + destDir
                                     + "\" does not exist "
                                     + "or is not a directory", getLocation());
        }
        if (includeAntRuntime == null && getProject().getProperty("build.sysclasspath") == null) {
            log(getLocation() + "warning: 'includeantruntime' was not set, " +
                    "defaulting to build.sysclasspath=last; set to false for repeatable builds",
                    Project.MSG_WARN);
        }
    }

    /**
     * Perform the compilation.
     *
     * @since Ant 1.5
     */
    protected void compile() {
        if (compileList.length == 0) {
            return;
        }
        logCompileStart();
        if (listFiles) {
            logFiles();
        }
        CompilerAdapter adapter = getAdapter();
        adapter.setJavac(this);
        boolean success = adapter.execute();
        if (success) {
            handleSuccess();
        } else {
            handleFailure();
        }
    }

    /**
     * Logs the start of the compilation.
     */
    private void logCompileStart() {
        log("Compiling " + compileList.length + " source file"
            + (compileList.length == 1 ? "" : "s")
            + (destDir != null ? " to " + destDir : ""));
    }

    /**
     * Logs each source file being compiled.
     */
    private void logFiles() {
        for (File file : compileList) {
            log(file.getAbsolutePath());
        }
    }

    /**
     * Retrieves the appropriate compiler adapter.
     *
     * @return the compiler adapter instance
     */
    private CompilerAdapter getAdapter() {
        String compilerImpl = getCompiler();
        return nestedAdapter != null ? nestedAdapter
            : CompilerAdapterFactory.getCompiler(compilerImpl, this,
                createCompilerClasspath());
    }

    /**
     * Handles the successful compilation path.
     */
    private void handleSuccess() {
        if (createMissingPackageInfoClass) {
            try {
                File dest = destDir != null ? destDir
                    : getProject().resolveFile(src.list()[0]);
                generateMissingPackageInfoClasses(dest);
            } catch (IOException x) {
                throw new BuildException(x, getLocation());
            }
        }
    }

    /**
     * Handles the failed compilation path.
     */
    private void handleFailure() {
        this.taskSuccess = false;
        if (errorProperty != null) {
            getProject().setNewProperty(errorProperty, "true");
        }
        if (failOnError) {
            throw new BuildException(FAIL_MSG, getLocation());
        } else {
            log(FAIL_MSG, Project.MSG_ERR);
        }
    }

