                if (!(o instanceof TemplateParameterSubstitution)) {
                    throw new IllegalArgumentException(
                            "The list of arguments must be instances" + //$NON-NLS-1$
                            " of TemplateParameterSubstitutions."); //$NON-NLS-1$
                }
