        RunnableClass run = new RunnableClass() {
            public void run() {
                Operation operation = createOperation();
                UMLUtil.getOwnedOperations((Type) cls).add(operation);
                operation.createReturnResult("return", (Type) returnType);
                if (name != null) {
                    operation.setName(name);
