    public AssociationClass buildAssociationClass(final Object end1,
            final Object end2) {
        if (!(end1 instanceof Type) || !(end2 instanceof Type)) {
            throw new IllegalArgumentException(
                    "end1 and end2 must be instances of Type"); //$NON-NLS-1$
        }
        if (((Type) end1).getNearestPackage() == null) {
            throw new NullPointerException(
                    "The containing package of " + //$NON-NLS-1$
                    "the end1 must be non-null."); //$NON-NLS-1$
        }
        RunnableClass run = new RunnableClass() {
            public void run() {
                AssociationClass associationClass = createAssociationClass();
                Property property1 = createAssociationEnd();
                Property property2 = createAssociationEnd();
                property1.setType((Type) end2);
                property2.setType((Type) end1);
                property1.setAssociation(associationClass);
                property2.setAssociation(associationClass);
                ((Type) end1).getNearestPackage().getPackagedElements().add(
                        associationClass);
                if (UMLUtil.getOwnedAttributes((Type) end1) == null) {
                    associationClass.getOwnedAttributes().add(property1);
                } else {
                    UMLUtil.getOwnedAttributes((Type) end1).add(property1);
                }
                if (UMLUtil.getOwnedAttributes((Type) end2) == null) {
                    associationClass.getOwnedAttributes().add(property2);
                } else {
                    UMLUtil.getOwnedAttributes((Type) end2).add(property2);
                }
                getParams().add(associationClass);
            }
        };
        ChangeCommand cmd = new ChangeCommand(
                modelImpl, run,
                "Create the association class # between # and #");
        editingDomain.getCommandStack().execute(cmd);
        cmd.setObjects(run.getParams().get(0), end1, end2);

        return (AssociationClass) run.getParams().get(0);
    }

    /**
     * Parameters for building an association end.
     */
    private static final class AssociationEndParams {
        final String name;
        final Type type;
        final Integer[] multi;
        final Stereotype stereo;
        final Boolean navigable;
        final Boolean order;
        final AggregationKind aggregation;
        final Boolean changeable;
        final VisibilityKind visibility;

        private AssociationEndParams(Builder builder) {
            this.name = builder.name;
            this.type = builder.type;
            this.multi = builder.multi;
            this.stereo = builder.stereo;
            this.navigable = builder.navigable;
            this.order = builder.order;
            this.aggregation = builder.aggregation;
            this.changeable = builder.changeable;
            this.visibility = builder.visibility;
        }

        static final class Builder {
            private String name;
            private Type type;
            private Integer[] multi;
            private Stereotype stereo;
            private Boolean navigable;
            private Boolean order;
            private AggregationKind aggregation;
            private Boolean changeable;
            private VisibilityKind visibility;

            Builder setName(String name) {
                this.name = name;
                return this;
            }

            Builder setType(Type type) {
                this.type = type;
                return this;
            }

            Builder setMulti(Integer[] multi) {
                this.multi = multi;
                return this;
            }

            Builder setStereo(Stereotype stereo) {
                this.stereo = stereo;
                return this;
            }

            Builder setNavigable(Boolean navigable) {
                this.navigable = navigable;
                return this;
            }

            Builder setOrder(Boolean order) {
                this.order = order;
                return this;
            }

            Builder setAggregation(AggregationKind aggregation) {
                this.aggregation = aggregation;
                return this;
            }

            Builder setChangeable(Boolean changeable) {
                this.changeable = changeable;
                return this;
            }

            Builder setVisibility(VisibilityKind visibility) {
                this.visibility = visibility;
                return this;
            }

            AssociationEndParams build() {
                return new AssociationEndParams(this);
            }
        }
    }

    private Property buildAssociationEndInternal(final Association assoc,
            final AssociationEndParams params) {
        Property property = createAssociationEnd();
        property.setType(params.type);
        property.setAssociation(assoc);
        if (params.name != null) {
            property.setName(params.name);
        }
        if (params.navigable != null) {
            property.setIsNavigable(params.navigable);
            if (!params.navigable) {
                assoc.getOwnedEnds().add(property);
            }
        }
        if (params.aggregation != null) {
            property.setAggregation(params.aggregation);
        }
        if (params.visibility != null) {
            property.setVisibility(params.visibility);
        }
        if (params.multi != null) {
            if (params.multi[0] != null) {
                property.setLower(params.multi[0]);
            }
            if (params.multi[1] != null) {
                property.setUpper(params.multi[1]);
            }
        }
        if (params.order != null) {
            property.setIsOrdered(params.order);
        }
        if (params.changeable != null) {
            property.setIsReadOnly(params.changeable);
        }
        if (params.stereo != null) {
            if (property.isStereotypeApplicable(params.stereo)) {
                property.applyStereotype(params.stereo);
            } 
        }
        return property;
    }

