    public Property buildAssociationEnd(Object assoc, String name, Object type,
            Integer[] multi, Object stereo, boolean navigable, Object order,
            Object aggregation, Object scope, Object changeable,
            Object visibility) {
        AssociationEndParams params = new AssociationEndParams.Builder()
                .setName(name)
                .setType((Type) type)
                .setMulti(multi)
                .setStereo((Stereotype) stereo)
                .setNavigable((Boolean) navigable)
                .setOrder((Boolean) order)
                .setAggregation((AggregationKind) aggregation)
                .setChangeable((Boolean) changeable)
                .setVisibility((VisibilityKind) visibility)
                .build();
        return buildAssociationEndInternal((Association) assoc, params);
    }

