    public Property buildAssociationEnd(Object assoc, String name, Object type,
            Integer[] multi, Object stereo, boolean navigable, Object order,
            Object aggregation, Object scope, Object changeable,
            Object visibility) {
        AssociationEndParams params = new AssociationEndParams.Builder()
                .assoc((Association) assoc)
                .name(name)
                .type((Type) type)
                .multi(multi)
                .stereo((Stereotype) stereo)
                .navigable(Boolean.valueOf(navigable))
                .order((Boolean) order)
                .aggregation((AggregationKind) aggregation)
                .changeable((Boolean) changeable)
                .visibility((VisibilityKind) visibility)
                .build();
        return buildAssociationEndInternal(params);
    }

