    public Object findOperationByName(Object trans, String opname) {
        if (!(trans instanceof Transition)) {
            throw new IllegalArgumentException();
        }
        try {
            Object sm = getStateMachine(trans);
            if (sm == null) {
                return null;
            }
            Object context = Model.getFacade().getContext(sm);
            Classifier classifier = getClassifierFromContext(context);
            if (classifier != null) {
                Operation op = findOperationInClassifier(classifier, opname);
                if (op != null) {
                    return op;
                }
            }
            Namespace pack = null;
            if (context instanceof UmlPackage) {
                pack = (Namespace) context;
            } else if (classifier != null) {
                Namespace parent = classifier.getNamespace();
                while (parent instanceof Classifier && parent.getNamespace() != null) {
                    parent = parent.getNamespace();
                }
                pack = parent;
            }
            if (pack != null) {
                Operation op = findOperationInNamespace(pack, opname);
                if (op != null) {
                    return op;
                }
            }
        } catch (InvalidObjectException e) {
            throw new InvalidElementException(e);
        }
        return null;
    }

    private Classifier getClassifierFromContext(Object context) {
        if (context instanceof Classifier) {
            return (Classifier) context;
        }
        if (context instanceof BehavioralFeature) {
            return ((BehavioralFeature) context).getOwner();
        }
        return null;
    }

    private Operation findOperationInClassifier(Classifier c, String opname) {
        for (Feature f : c.getFeature()) {
            if (f instanceof Operation && opname.equals(f.getName())) {
                return (Operation) f;
            }
        }
        return null;
    }

    private Operation findOperationInNamespace(Namespace ns, String opname) {
        for (ModelElement me : ns.getOwnedElement()) {
            if (me instanceof Classifier) {
                Operation op = findOperationInClassifier((Classifier) me, opname);
                if (op != null) {
                    return op;
                }
            }
        }
        return null;
    }


