    public Object findOperationByName(Object trans, String opname) {
        if (!(trans instanceof Transition)) {
            throw new IllegalArgumentException();
        }
        try {
            Object sm = getStateMachine(trans);
            Object context = Model.getFacade().getContext(sm);
            Classifier classifier = getClassifierFromContext(context);
            if (classifier != null) {
                Object op = findOperationInClassifier(classifier, opname);
                if (op != null) {
                    return op;
                }
            }
            Namespace ns = getNamespaceForContext(context, classifier);
            if (ns != null) {
                Object op = findOperationInNamespace(ns, opname);
                if (op != null) {
                    return op;
                }
            }
        } catch (InvalidObjectException e) {
            throw new InvalidElementException(e);
        }
        return null;
    }

    /**
     * Extracts the classifier from the given context.
     *
     * @param context the context object
     * @return the classifier or {@code null} if none
     */
    private Classifier getClassifierFromContext(Object context) {
        if (context instanceof Classifier) {
            return (Classifier) context;
        }
        if (context instanceof BehavioralFeature) {
            return ((BehavioralFeature) context).getOwner();
        }
        return null;
    }

    /**
     * Determines the namespace that should be searched for operations.
     *
     * @param context the context object
     * @param classifier the classifier derived from the context
     * @return the namespace or {@code null} if none
     * @throws InvalidObjectException if namespace resolution fails
     */
    private Namespace getNamespaceForContext(Object context, Classifier classifier)
            throws InvalidObjectException {
        if (context instanceof UmlPackage) {
            return (Namespace) context;
        }
        if (classifier != null) {
            Namespace parent = classifier.getNamespace();
            while (parent instanceof Classifier) {
                if (parent.getNamespace() == null) {
                    break;
                }
                parent = parent.getNamespace();
            }
            return parent;
        }
        return null;
    }

    /**
     * Searches for an operation with the given name in the specified classifier.
     *
     * @param classifier the classifier to search
     * @param opname the operation name
     * @return the operation or {@code null} if not found
     */
    private Object findOperationInClassifier(Classifier classifier, String opname) {
        List<Feature> features = classifier.getFeature();
        for (Feature f : features) {
            if (f instanceof Operation && opname.equals(f.getName())) {
                return f;
            }
        }
        return null;
    }

    /**
     * Searches for an operation with the given name in the specified namespace.
     *
     * @param ns the namespace to search
     * @param opname the operation name
     * @return the operation or {@code null} if not found
     */
    private Object findOperationInNamespace(Namespace ns, String opname) {
        Collection<ModelElement> mes = ns.getOwnedElement();
        for (ModelElement me : mes) {
            if (me instanceof Classifier) {
                Classifier c = (Classifier) me;
                List<Feature> features = c.getFeature();
                for (Feature f : features) {
                    if (f instanceof Operation && opname.equals(f.getName())) {
                        return f;
                    }
                }
            }
        }
        return null;
    }


    // TODO: getAllPossibleSubvertices and getAllSubStates are duplicates - tfm
    public Collection<StateVertex> getAllSubStates(Object compState) {
        try {
            if (compState instanceof CompositeState) {
                Collection<StateVertex> result = new ArrayList<StateVertex>();
                for (Object subState : Model.getFacade().getSubvertices(
                        compState)) {
                    if (subState instanceof CompositeState) {
                        result.addAll(getAllSubStates(subState));
                    }
                    result.add((StateVertex) subState);
                }
                return result;
            }
        } catch (InvalidObjectException e) {
            throw new InvalidElementException(e);
        }
        throw new IllegalArgumentException(
                "Argument is not a composite state");
    }

    public Collection<Transition> getTransitions(Object handle,
            boolean includeInternals) {
        if (handle instanceof StateMachine) {
            Collection<Transition> result = new ArrayList<Transition>();
            result.addAll(((StateMachine) handle).getTransitions());
            if (includeInternals) {
                State top = ((StateMachine) handle).getTop();
                if (top != null && top instanceof CompositeState) {
                    Collection<StateVertex> subs = getAllSubStates(top);
                    for (StateVertex sub : subs) {
                        if (sub instanceof State) {
                            result.addAll(((State) sub).getInternalTransition());
                        }
                    }
                }
            }
            return result;
        }
        throw new IllegalArgumentException(
            "Argument is not a statemachine");
    }

